    t=re.sub(r'<w:instrText[^>]*>.*?</w:instrText>','',t,flags=re.S)
    plain=re.sub(r'<[^>]+>','',t)
    toks=re.findall(r'[\[\(]\d[\d, \u2013]*[\]\)]', plain)
    return [t for t in toks]
old=tokens('doc_backup.xml'); new=tokens('unpacked/word/document.xml')
def isnum(t): return re.fullmatch(r'[\[\(]\d[\d, \u2013]*[\]\)]', t) and not re.fullmatch(r'[\[\(](19|20)\d\d[\]\)]', t)
def bump(t): return re.sub(r'\d+', lambda m: str(int(m.group())+1), t)
# align: new has one extra leading token [1]
assert new[0]=='[1]'
newa=new[1:]
assert len(old)==len(newa), (len(old), len(newa))
