for a,b in zip(old,newa):
    if a in ('(2009)','(2012–2014)','(2018)','(11)','(0–4)','(0–5)'):
        if a!=b: bad.append((a,b,'should be unchanged'))
    elif b!=bump(a):
        bad.append((a,b,'bump mismatch'))
print('problems:',bad if bad else 'none')
